rowClick.customFunction:
// rowClick — modifier-key aware navigation.
// $event has the original mouse event so we can detect Shift / Ctrl / Cmd.
try {
    var devId   = (entityId && entityId.id)   ? entityId.id   : entityId;
    var devType = (entityId && entityId.entityType) ? entityId.entityType : 'DEVICE';
    var stateParams = {
        device_id: { entityId: { entityType: devType, id: devId }, entityName: entityName }
    };

    var sc = widgetContext.stateController;
    var newTab = $event && ($event.shiftKey || $event.ctrlKey || $event.metaKey || $event.button === 1);

    if (newTab) {
        // Build a URL to the same dashboard with the device state pushed on top
        // of whatever state is currently encoded in the URL. The original tab
        // is left untouched, so its search box stays filled in.
        try {
            var url = new URL(window.location.href);
            var existing = [];
            var st = url.searchParams.get('state');
            if (st) {
                try { existing = JSON.parse(decodeURIComponent(escape(atob(st)))); }
                catch (_) { existing = []; }
                if (!Array.isArray(existing)) existing = [];
            }
            existing.push({ id: 'device_home', params: stateParams });
            var encoded = btoa(unescape(encodeURIComponent(JSON.stringify(existing))));
            url.searchParams.set('state', encoded);
            window.open(url.toString(), '_blank', 'noopener');
            if ($event && $event.preventDefault) $event.preventDefault();
            if ($event && $event.stopPropagation) $event.stopPropagation();
            return;
        } catch (e) {
            console.error('[Devices rowClick] new-tab build failed, falling back', e);
            // Fall through to same-tab navigation if URL construction failed.
        }
    }

    if (sc && typeof sc.openState === 'function') {
        sc.openState('device_home', stateParams);
    } else {
        console.error('[Devices rowClick] stateController.openState unavailable');
    }
} catch (e) {
    console.error('[Devices rowClick] error', e);
}

headerButton.customFunction:
// Access widget context
var data = widgetContext.data; // Timeseries data
var timeWindow = widgetContext.timeWindow; // Time window for start/end time
var http = widgetContext.http;

function formatLocalDate(timestamp) {
    var date = new Date(timestamp);
    var year = date.getFullYear();
    var month = String(date.getMonth() + 1).padStart(2, '0');
    var day = String(date.getDate()).padStart(2, '0');
    var hours = String(date.getHours()).padStart(2, '0');
    var minutes = String(date.getMinutes()).padStart(2, '0');
    var seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// Collect unique entities with their IDs
var macIds = [];
var entityInfo = {};
data.forEach(function(ds) {
    var eName = ds.datasource.entityName;
    if (!entityInfo[eName]) {
        macIds.push(eName);
        entityInfo[eName] = {
            entityId: ds.datasource.entityId,
            entityLabel: ds.datasource.entityLabel || eName,
            deviceName: null
        };
    }
});

var startTime = new Date(timeWindow.minTime).toISOString();
var endTime = new Date(timeWindow.maxTime).toISOString();

// Fetch deviceName client attribute for each entity, then generate CSV
var pending = macIds.length;

function onAllResolved() {
    var csvContent = "data:text/csv;charset=utf-8,";

    // Build deviceNameMap: deviceName attribute -> entityLabel -> entityName
    var deviceNameMap = {};
    macIds.forEach(function(eName) {
        var info = entityInfo[eName];
        deviceNameMap[eName] = info.deviceName || info.entityLabel || eName;
    });

    var deviceNames = macIds.map(function(m) { return deviceNameMap[m]; });

    // Add metadata
    csvContent += "Device(s)," + deviceNames.join("; ") + "\n";
    csvContent += "Mac ID(s)," + macIds.join("; ") + "\n";
    csvContent += "Start Time," + startTime + "\n";
    csvContent += "End Time," + endTime + "\n";
    csvContent += "\n";

    // Create CSV headers
    var headers = ["Timestamp"];
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        headers.push(displayName + " - " + ds.dataKey.label);
    });
    csvContent += headers.join(",") + "\n";

    // Process timeseries data
    var rows = {};
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        ds.data.forEach(function(point) {
            var timestamp = point[0];
            var value = point[1];
            if (!rows[timestamp]) {
                rows[timestamp] = { timestamp: formatLocalDate(timestamp), values: {} };
            }
            rows[timestamp].values[displayName + " - " + ds.dataKey.label] = value;
        });
    });

    // Convert rows to CSV
    Object.keys(rows).forEach(function(timestamp) {
        var row = [rows[timestamp].timestamp];
        headers.slice(1).forEach(function(header) {
            row.push(rows[timestamp].values[header] || "");
        });
        csvContent += row.join(",") + "\n";
    });

    // Trigger CSV download
    var encodedUri = encodeURI(csvContent);
    var link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", deviceNames.join("; ") + "_current_voltage_" + startTime.split(" ")[0] + "_" + endTime.split(" ")[0] + ".csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// Fetch deviceName attribute for each device via API
macIds.forEach(function(eName) {
    var info = entityInfo[eName];
    var url = '/api/plugins/telemetry/DEVICE/' + info.entityId + '/values/attributes/CLIENT_SCOPE?keys=deviceName';
    http.get(url).subscribe(
        function(response) {
            if (response && response.length > 0) {
                response.forEach(function(attr) {
                    if (attr.key === 'deviceName' && attr.value) {
                        info.deviceName = attr.value;
                    }
                });
            }
            pending--;
            if (pending === 0) onAllResolved();
        },
        function(error) {
            pending--;
            if (pending === 0) onAllResolved();
        }
    );
});

// Download the current device-list table as CSV (one row per device).
var data = widgetContext.data || [];

function csvEscape(v) {
    if (v === null || v === undefined) v = '';
    v = String(v);
    if (/[",\n]/.test(v)) {
        v = '"' + v.replace(/"/g, '""') + '"';
    }
    return v;
}

function fmt(label, value) {
    if (value === null || value === undefined || value === '') return '';
    var l = String(label).toLowerCase();
    if (l === 'active') {
        return (String(value) === 'true') ? 'Online' : 'Offline';
    }
    if (l === 'on - off') {
        return (String(value) === 'true') ? 'ON' : 'OFF';
    }
    if (l === 'last activity') {
        var n = Number(value);
        if (!isNaN(n) && n > 0) {
            return moment(n).format('DD/MM/YYYY HH:mm:ss');
        }
    }
    return value;
}

var headers = [];
var seen = {};
var entities = {};
var order = [];

data.forEach(function(ds) {
    var label = ds.dataKey.label;
    if (!seen[label]) { seen[label] = true; headers.push(label); }
    var eName = ds.datasource.entityName;
    if (!entities[eName]) { entities[eName] = {}; order.push(eName); }
    var v = '';
    if (ds.data && ds.data.length) { v = ds.data[ds.data.length - 1][1]; }
    entities[eName][label] = v;
});

if (!order.length) {
    return;
}

var lines = [];
lines.push(headers.map(csvEscape).join(','));

order.forEach(function(eName) {
    var row = entities[eName];
    var cells = headers.map(function(h) {
        return csvEscape(fmt(h, row[h]));
    });
    lines.push(cells.join(','));
});

var csv = lines.join('\n');
var blob = new Blob(["﻿" + csv], { type: 'text/csv;charset=utf-8;' });
var url = URL.createObjectURL(blob);
var link = document.createElement('a');
link.setAttribute('href', url);
var ts = moment().format('YYYY-MM-DD_HH-mm');
link.setAttribute('download', 'device_list_' + ts + '.csv');
document.body.appendChild(link);
link.click();
document.body.removeChild(link);
URL.revokeObjectURL(url);
